using Godot;
namespace LibreKO.Editors.Desktop;
public partial class PreviewViewport:SubViewportContainer {
 readonly SubViewport viewport;readonly Node3D pivot=new();readonly Camera3D camera;float distance=3.8f,yaw,pitch;Vector3 aim=new(0,1,0);public Node3D? Model{get;private set;}
 public PreviewViewport(){Stretch=true;SizeFlagsHorizontal=SizeFlags.ExpandFill;SizeFlagsVertical=SizeFlags.ExpandFill;CustomMinimumSize=new(360,330);viewport=new(){OwnWorld3D=true,Size=new(650,650),RenderTargetUpdateMode=SubViewport.UpdateMode.Always};AddChild(viewport);viewport.AddChild(new WorldEnvironment{Environment=new Godot.Environment{BackgroundMode=Godot.Environment.BGMode.Color,BackgroundColor=new("#151518"),AmbientLightSource=Godot.Environment.AmbientSource.Color,AmbientLightColor=new("#d4d0c8"),AmbientLightEnergy=0.8f,TonemapMode=Godot.Environment.ToneMapper.Filmic}});viewport.AddChild(new DirectionalLight3D{RotationDegrees=new(-35,-35,0),LightEnergy=1.6f});viewport.AddChild(new DirectionalLight3D{RotationDegrees=new(-15,145,0),LightEnergy=0.7f,LightColor=new("#c8c5bb")});viewport.AddChild(pivot);camera=new(){Current=true,Fov=35};viewport.AddChild(camera);GuiInput+=Input;LibreKO.FxLayer.Attach(viewport);ResetView();}
 public void ShowModel(Node3D? model){if(Model!=null){pivot.RemoveChild(Model);Model.QueueFree();}Model=model;if(model!=null)pivot.AddChild(model);ResetView();}
 public void ResetView(){yaw=0;pitch=0;distance=3.8f;aim=new(0,0.9f,0);if(Model!=null){Aabb? bounds=null;foreach(var n in Model.FindChildren("*","MeshInstance3D",true,false)){var m=(MeshInstance3D)n;if(m.Mesh==null||PreviewEffects.IsEffect(m))continue;var b=m.GlobalTransform*m.GetAabb();bounds=bounds.HasValue?bounds.Value.Merge(b):b;}if(bounds is {} box){aim=box.GetCenter();distance=Math.Max(box.Size.Length()*1.5f,0.4f);}}Place();}
 void Place(){pivot.Rotation=new(pitch,yaw,0);camera.Position=aim+new Vector3(0,0,distance);camera.Rotation=Vector3.Zero;}
 void Input(InputEvent e){if(e is InputEventMouseMotion move&&(move.ButtonMask&MouseButtonMask.Left)!=0){yaw+=move.Relative.X*0.01f;pitch=Math.Clamp(pitch+move.Relative.Y*0.005f,-0.8f,0.8f);Place();}if(e is InputEventMouseButton b&&b.Pressed){if(b.ButtonIndex==MouseButton.WheelUp)distance*=0.9f;if(b.ButtonIndex==MouseButton.WheelDown)distance*=1.1f;Place();}}
 public AnimationPlayer? Animation=>Model?.FindChildren("*","AnimationPlayer",true,false).OfType<AnimationPlayer>().FirstOrDefault();
 public void SetLighting(int preset){var env=viewport.GetChildren().OfType<WorldEnvironment>().First().Environment;env.AmbientLightEnergy=preset==1?1.25f:preset==2?0.25f:0.8f;env.BackgroundColor=new(preset==1?"#303033":preset==2?"#09090b":"#151518");}
 public void Play(string name){var anim=Animation;if(anim==null||!anim.HasAnimation(name))return;anim.GetAnimation(name).LoopMode=Godot.Animation.LoopModeEnum.Linear;anim.Play(name);}
 public static Node3D? Character(int race,int face,int hair,int[]? gear=null)=>LibreKO.CharacterPreview.Build(race,face,gear??new int[17],LibreKO.Domain.HairCode.StyleOf(hair),LibreKO.Domain.HairCode.TintOf(hair),enableShine:true);
}
